#[derive(Clone, Debug, Eq, PartialEq)]
pub struct DocumentOpenFailure {
    pub path: PathBuf,
    pub message: String,
}

impl DocumentOpenFailure {
    fn presentation(&self) -> String {
        let name = self
            .path
            .file_name()
            .unwrap_or_else(|| self.path.as_os_str())
            .to_string_lossy();
        format!("{name}: {}", self.message)
    }
}

