    /// Allocates document ids from `source`, shared with other windows.
    pub fn share_document_ids(&mut self, source: Arc<std::sync::atomic::AtomicU64>) {
        self.document_id_source = Some(source);
    }

    fn peek_document_id(&self) -> DocumentId {
        DocumentId::new(match &self.document_id_source {
            Some(source) => source.load(std::sync::atomic::Ordering::Relaxed),
            None => self.next_document_id,
        })
    }

    fn allocate_document_id(&mut self) -> DocumentId {
        match &self.document_id_source {
            Some(source) => {
                DocumentId::new(source.fetch_add(1, std::sync::atomic::Ordering::Relaxed))
            }
            None => {
                let document_id = DocumentId::new(self.next_document_id);
                self.next_document_id = self.next_document_id.saturating_add(1);
                document_id
            }
        }
    }

    /// Rendered bounds of the tab at `index` and of the whole tab strip, in
    /// window coordinates (for development review tooling).
    pub fn session_tab_geometry(
        &self,
        index: usize,
        cx: &App,
    ) -> (Option<Bounds<Pixels>>, Bounds<Pixels>) {
        let tab = self
            .sessions
            .get(index)
            .and_then(|session| self.session_tab_bounds.get(&session.read(cx).id))
            .map(|bounds| bounds.get());
        (tab, self.session_tab_strip_bounds.get())
    }

    /// The dragged tab and whether the drag has passed its threshold.
    pub fn session_tab_drag_state(&self) -> Option<(DocumentId, bool)> {
        self.session_tab_pointer_drag
            .as_ref()
            .map(|drag| (drag.document_id, drag.activated))
    }

    /// Every tab's and close button's bounds, for development review tooling.
    pub fn session_tab_debug_geometry(&self, cx: &App) -> Vec<(DocumentId, Bounds<Pixels>, Option<Bounds<Pixels>>)> {
        self.sessions
            .iter()
            .filter_map(|session| {
                let id = session.read(cx).id;
                Some((
                    id,
                    self.session_tab_bounds.get(&id)?.get(),
                    self.session_tab_close_bounds.get(&id).map(|bounds| bounds.get()),
                ))
            })
            .collect()
    }

    /// Each document's load and save state, for development review tooling.
    pub fn session_debug_states(&self, cx: &App) -> Vec<String> {
        self.sessions
            .iter()
            .map(|session| {
                let session = session.read(cx);
                format!("{}: {:?} / {:?}", session.title, session.status, session.save_status)
            })
            .collect()
    }

    /// The visible tab strip area, for development review tooling.
    pub fn session_tab_viewport(&self) -> Bounds<Pixels> {
        self.session_tab_scroll.bounds()
    }

    pub fn session_titles(&self, cx: &App) -> Vec<String> {
        self.sessions
            .iter()
            .map(|session| session.read(cx).title.clone())
            .collect()
    }

    pub fn session_count(&self) -> usize {
        self.sessions.len()
    }

    /// The tab-strip insertion index for a point in this window, or `None`
    /// when the point is not over the tab strip.
    pub fn tab_insertion_index(&self, position: Point<Pixels>, cx: &App) -> Option<usize> {
        let strip = self.session_tab_strip_bounds.get();
        if strip.size.width <= px(0.) || !strip.contains(&position) {
            return None;
        }
        Some(
            self.sessions
                .iter()
                .filter(|session| {
                    self.session_tab_bounds
                        .get(&session.read(cx).id)
                        .is_some_and(|bounds| bounds.get().center().x < position.x)
                })
                .count(),
        )
    }

    /// While true, the dragged tab's in-window copy is hidden beyond the strip
    /// because the application shows it in a window that can leave this one.
    pub fn set_external_tab_drag_preview(&mut self, active: bool, cx: &mut Context<Self>) {
        if self.external_tab_drag_preview != active {
            self.external_tab_drag_preview = active;
            cx.notify();
        }
    }

    pub fn document_title(&self, document_id: DocumentId, cx: &App) -> Option<String> {
        self.session(document_id, cx).map(|session| session.read(cx).title.clone())
    }

    /// Shows where a tab dragged from another window would be inserted.
    pub fn set_incoming_tab_drop(&mut self, index: Option<usize>, cx: &mut Context<Self>) {
        if self.incoming_tab_drop != index {
            self.incoming_tab_drop = index;
            cx.notify();
        }
    }

    /// Whether `document_id` can move to another window now: it is loaded,
    /// not saving, closing or awaiting recovery confirmation.
    pub fn can_transfer_document(&self, document_id: DocumentId, cx: &App) -> bool {
        self.session(document_id, cx).is_some_and(|session| {
            let session = session.read(cx);
            matches!(session.status, NativeDocumentStatus::Ready)
                && session.save_status != NativeDocumentSaveStatus::Saving
        }) && self.pending_close_document_id != Some(document_id)
            && self.close_after_save_document_id != Some(document_id)
            && !self.recovery_confirmation_pending.contains(&document_id)
    }

    /// Removes an open document without releasing it, keeping its edits,
    /// history and recovery checkpoint, so another window can adopt it.
    pub fn detach_document(
        &mut self,
        document_id: DocumentId,
        cx: &mut Context<Self>,
    ) -> Result<DetachedDocument, String> {
        if !self.can_transfer_document(document_id, cx) {
            return Err("This document is busy and cannot move to another window yet.".into());
        }
        if self.active_document_id == Some(document_id) {
            self.commit_pending_text_editor_before_application_close(cx)?;
        }
        let Some(index) = self
            .sessions
            .iter()
            .position(|session| session.read(cx).id == document_id)
        else {
            return Err("The document is no longer open.".into());
        };
        if self.signature_popover_open && self.active_document_id == Some(document_id) {
            self.dismiss_signature_popover(document_id, None, cx);
        }
        if self
            .active_annotation_pointer
            .is_some_and(|active| active.document_id == document_id)
        {
            self.cancel_annotation_pointer(cx);
        }
        if let Some(control) = self.page_scale_control.clone() {
            control.update(cx, |control, cx| control.cancel_for_document(document_id, cx));
        }
        self.viewer_session_subscriptions.remove(&document_id);
        self.viewer_quality_tasks.remove(&document_id);
        self.session_tab_focus_handles.remove(&document_id);
        self.session_tab_bounds.remove(&document_id);
        self.session_tab_close_bounds.remove(&document_id);
        self.session_tab_pointer_drag = None;
        if self.suppress_session_tab_click_id == Some(document_id) {
            self.suppress_session_tab_click_id = None;
        }
        if self.session_tab_hovered == Some(document_id) {
            self.session_tab_hovered = None;
        }
        let session = self.sessions.remove(index);
        self.page_interactions.retain(|(owner, _), _| *owner != document_id);
        self.last_painted_page_evidence
            .retain(|(owner, _), _| *owner != document_id);
        self.viewport_bounds.remove(&document_id);
        self.viewport_painted_scroll.remove(&document_id);
        self.annotation_statuses.remove(&document_id);
        if self.active_document_id == Some(document_id) {
            self.active_document_id = self
                .sessions
                .iter()
                .skip(index)
                .chain(self.sessions[..index].iter().rev())
                .find_map(|session| {
                    matches!(session.read(cx).status, NativeDocumentStatus::Ready)
                        .then_some(session.read(cx).id)
                });
        }
        self.sync_active_viewer_toolbar(cx);
        self.session_tab_reveal = self.active_document_id;
        cx.notify();
        Ok(DetachedDocument { session })
    }

    /// Adopts a document detached from another window at tab `index` and
    /// makes it active.
    pub fn attach_document(
        &mut self,
        document: DetachedDocument,
        index: usize,
        cx: &mut Context<Self>,
    ) -> DocumentId {
        let session = document.session;
        let document_id = session.read(cx).id;
        session.update(cx, |session, _| {
            let _ = session
                .annotations
                .set_semantic_snap_settings(self.semantic_snap_settings);
        });
        self.observe_viewer_session(&session, cx);
        self.register_session_tab(document_id, cx);
        let index = index.min(self.sessions.len());
        self.sessions.insert(index, session);
        self.pending_session_restore = None;
        self.activate_document(document_id, cx);
        self.session_tab_reveal = Some(document_id);
        cx.notify();
        document_id
    }

    /// Lets opens check the application's other windows: when `focus` finds
    /// the path already open elsewhere, it brings that document forward and
    /// returns true, and this workspace does not open a second copy.
    pub fn set_other_window_document_focus(
        &mut self,
        focus: impl Fn(gpui::EntityId, &Path, &mut App) -> bool + 'static,
    ) {
        self.other_window_document_focus = Some(std::rc::Rc::new(focus));
    }

    /// The open (not failed) document at `path`, if any.
    pub fn document_id_for_path(&self, path: &Path, cx: &App) -> Option<DocumentId> {
        self.sessions.iter().find_map(|session| {
            let session = session.read(cx);
            (!matches!(session.status, NativeDocumentStatus::Failed(_))
                && normalized_document_path(&session.path) == normalized_document_path(path))
            .then_some(session.id)
        })
    }

    pub fn use_external_template_authority(&mut self, enabled: bool) {
        self.external_template_authority = enabled;
    }

    pub fn apply_template_catalog(
        &mut self,
        templates: Vec<TemplateCatalogItem>,
        durable_last_used_id: impl Into<String>,
        cx: &mut Context<Self>,
    ) {
        self.template_control.update(cx, |control, cx| {
            control.apply_template_catalog(templates, durable_last_used_id, cx);
        });
        cx.notify();
    }

    pub fn set_template_operation_state(&mut self, storage_busy: bool, cx: &mut Context<Self>) {
        let save_document_enabled = self.active_document_id.is_some() && !storage_busy;
        self.template_control.update(cx, |control, cx| {
            control.set_creating(storage_busy, cx);
            control.set_save_document_enabled(save_document_enabled, cx);
        });
    }

    fn handle_template_split_event(&mut self, event: TemplateSplitEvent, cx: &mut Context<Self>) {
        match event {
            TemplateSplitEvent::CreateRequested {
                template_id,
                origin,
            } => {
                if self.external_template_authority {
                    cx.emit(DocumentWorkspaceTemplateCommand::Create(
                        TemplateCreationEvent {
                            template_id,
                            origin,
                        },
                    ));
                    return;
                }
                if self.pending_template_id.is_some() {
                    return;
                }
                self.pending_template_id = Some(template_id.clone());
                let workspace = cx.entity().downgrade();
                cx.defer(move |cx| {
                    let _ = workspace.update(cx, |workspace, cx| {
                        workspace.start_reserved_template_creation(template_id, cx);
                    });
                });
                cx.notify();
            }
            TemplateSplitEvent::ManageRequested => {
                self.template_manage_requests = self.template_manage_requests.saturating_add(1);
                cx.emit(DocumentWorkspaceTemplateCommand::Manage);
                cx.notify();
            }
            TemplateSplitEvent::SaveDocumentAsTemplateRequested => {
                self.template_save_requests = self.template_save_requests.saturating_add(1);
                if let Some(document_id) = self.active_document_id
                    && let Some(session) = self.session(document_id, cx)
                {
                    let session = session.read(cx);
                    cx.emit(DocumentWorkspaceTemplateCommand::SaveDocumentAsTemplate {
                        document_id,
                        document_name: session.title().to_owned(),
                        authorized_source: session.path().to_owned(),
                    });
                }
                cx.notify();
            }
            TemplateSplitEvent::OpenChanged(_) | TemplateSplitEvent::SelectionChanged(_) => {}
        }
    }

    pub fn request_generated_template(
        &mut self,
        template_id: &'static str,
        cx: &mut Context<Self>,
    ) -> GeneratedTemplateRequestDisposition {
        if self.pending_template_id.is_some() {
            return GeneratedTemplateRequestDisposition::SuppressedPending;
        }
        self.pending_template_id = Some(template_id.to_owned());
        self.start_reserved_template_creation(template_id.to_owned(), cx)
    }

    fn start_reserved_template_creation(
        &mut self,
        template_id: String,
        cx: &mut Context<Self>,
    ) -> GeneratedTemplateRequestDisposition {
        if self.pending_template_id.as_deref() != Some(template_id.as_str())
            || self.pending_template_document_id.is_some()
        {
            return GeneratedTemplateRequestDisposition::SuppressedPending;
        }
        self.template_control.update(cx, |control, cx| {
            control.set_creating(true, cx);
        });
        let Some(store) = self.generated_document_store.clone() else {
            let error =
                "Generated template storage is not configured for this workspace.".to_owned();
            self.last_file_error = Some(error.clone());
            self.finish_template_creation(cx);
            return GeneratedTemplateRequestDisposition::Rejected(error);
        };
        let request = match generated_document_request_for_template(&template_id) {
            Ok(request) => request,
            Err(error) => {
                self.last_file_error = Some(error.clone());
                self.finish_template_creation(cx);
                return GeneratedTemplateRequestDisposition::Rejected(error);
            }
        };
        match self.create_generated_document(store, request, cx) {
            Ok(document_id) => {
                self.pending_template_document_id = Some(document_id);
                GeneratedTemplateRequestDisposition::Started(document_id)
            }
            Err(error) => {
                self.last_file_error = Some(error.clone());
                self.finish_template_creation(cx);
                GeneratedTemplateRequestDisposition::Rejected(error)
            }
        }
    }

    fn finish_template_creation(&mut self, cx: &mut Context<Self>) {
        self.pending_template_id = None;
        self.pending_template_document_id = None;
        self.template_control.update(cx, |control, cx| {
            control.set_creating(false, cx);
        });
        cx.notify();
    }

